SELECT * FROM biz_comment
WHERE deleted = 0
  AND status = 1
  AND user_id = #{userId}
  AND target_id = #{targetId}
  AND target_type = #{targetType}
  AND parent_id IS NULL
LIMIT 1

SELECT AVG(rating) FROM biz_comment
WHERE deleted = 0
  AND status = 1
  AND target_id = #{targetId}
  AND target_type = #{targetType}
  AND rating IS NOT NULL
